mapper.select:
SELECT COUNT(*) > 0
FROM app_user
WHERE account_number = #{accountNumber}

SELECT user_id, registration_id, account_number, phone_number, real_name, nickname, phone_tail, identity_status, status, version, created_at, updated_at, id_card, id_card_hash FROM app_user WHERE status = 'ACTIVE' AND ( phone_number = #{keyword} OR nickname LIKE CONCAT(#{keyword}, '%') OR real_name LIKE CONCAT(#{keyword}, '%') )
AND user_id != #{excludeId}
ORDER BY CASE WHEN phone_number = #{keyword} THEN 0 ELSE 1 END, account_number ASC LIMIT #{limit}

SELECT u.user_id, u.registration_id, u.account_number, u.phone_number, u.real_name, u.nickname, u.phone_tail, u.identity_status, u.status, u.version, u.created_at, u.updated_at, u.disabled_by, u.disabled_reason, c.login_lock_until, u.id_card, u.id_card_hash FROM app_user u LEFT JOIN credential c ON c.user_id = u.user_id
u.status = #{status}
AND LOWER(u.account_number) LIKE CONCAT('%', LOWER(#{loginName}), '%')
AND u.user_id > #{cursor}
ORDER BY u.user_id ASC LIMIT #{limit}
